literal:
CREATE TABLE IF NOT EXISTS %1$s(
  ID                INT        NOT NULL,
  AFF_%1$s        INT        NOT NULL,
  NAME              VARCHAR2(100),
  PRIMARY KEY (ID, AFF_%1$s)
) with "TEMPLATE=%2$s,KEY_TYPE=%1$s_KEY, AFFINITY_KEY=AFF_%1$s, CACHE_NAME=%1$s_CACHE, VALUE_TYPE=%1$s_VALUE, ATOMICITY=TRANSACTIONAL";
